import random

def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'C' if history[0][1] == 'C' else 'D'

    my_last, opp_last = history[-1]

    # Counters
    opp_c = 0
    opp_d = 0
    for _, o in history:
        if o == 'C':
            opp_c += 1
        else:
            opp_d += 1

    # Recent window analysis
    window_size = 10 if n >= 10 else n
    recent = history[-window_size:]
    recent_opp_c = 0
    recent_opp_d = 0
    for _, o in recent:
        if o == 'C':
            recent_opp_c += 1
        else:
            recent_opp_d += 1

    # Long-run cooperation rate
    coop_rate = opp_c / n
    recent_coop = recent_opp_c / window_size

    # Detect pure strategies quickly
    if opp_d == 0:
        # Always-cooperative opponent: exploit occasionally early, then more late
        if n < 20:
            return 'C'
        if n >= 90:
            return 'D'
        return 'D' if rng.random() < 0.1 else 'C'

    if opp_c == 0:
        return 'D'

    # Detect runs of D at end
    run_d = 0
    for _, o in reversed(history):
        if o == 'D':
            run_d += 1
        else:
            break

    # Detect alternation D C D C ... in opponent's recent moves
    if n >= 6:
        last6 = [o for _, o in history[-6:]]
        alt = True
        for i in range(1, 6):
            if last6[i] == last6[i - 1]:
                alt = False
                break
        if alt:
            # Predict next opponent move
            predicted = last6[0] if (6 % 2 == 0) else last6[1]
            # Actually next after last6[-1]: opposite of last6[-1] due to alternation
            predicted = 'C' if last6[-1] == 'D' else 'D'
            if predicted == 'C':
                return 'D'
            return 'D'

    # Chronic defector: punish hard
    if recent_opp_d >= 8 and coop_rate < 0.5:
        # Break cycle occasionally
        if run_d >= 6 and rng.random() < 0.15:
            return 'C'
        return 'D'

    # Highly cooperative opponent: mostly cooperate, probe occasionally
    if recent_coop >= 0.85:
        if n >= 90:
            return 'D'
        # Rare probing exploit
        if my_last == 'C' and opp_last == 'C' and rng.random() < 0.06:
            return 'D'
        # Recover after our defection
        if my_last == 'D':
            return 'C'
        return 'C'

    # Mutual defection trap: try to escape
    if run_d >= 4:
        if rng.random() < 0.3:
            return 'C'
        return 'D'

    # Standard: retaliate against last defection but forgive if generally cooperative
    if opp_last == 'D':
        if my_last == 'D':
            # Both defected; try occasional recovery when opponent usually cooperates
            if coop_rate > 0.5 and rng.random() < 0.3:
                return 'C'
            return 'D'
        # We cooperated, they defected: retaliate
        if coop_rate > 0.7 and rng.random() < 0.2:
            return 'C'
        return 'D'

    # opp_last == 'C'
    if recent_opp_d >= 3 and coop_rate < 0.6:
        # Mixed opponent, opportunistic
        if rng.random() < 0.3:
            return 'D'
        return 'C'
    # Return to cooperation after punishment
    return 'C'
